import numpy as np
# net cells (col,row) as printed; views: (top, front-right, front-left); top->right->left is clockwise from outside
nets = {'A': {(0,0):5,(1,0):1,(1,1):4,(1,2):6,(1,3):2,(2,3):3},
        'B': {(0,0):5,(1,0):1,(1,1):4,(1,2):2,(1,3):6,(2,3):3},
        'C': {(0,0):5,(1,0):1,(1,1):3,(1,2):2,(1,3):4,(2,3):6},
        'D': {(0,0):5,(1,0):1,(1,1):4,(1,2):6,(1,3):3,(2,3):2}}
views = [(5,1,4), (4,3,6), (2,5,6)]
def fold(net):  # x right, y up, z = printed side (outside); state (normal n, net +x dir u, net +y dir v)
    s = next(iter(net)); st = {s: (np.array([0,0,1]), np.array([1,0,0]), np.array([0,1,0]))}; stack = [s]
    while stack:
        c = stack.pop(); n, u, v = st[c]
        for d, new in {(1,0): (u,-n,v), (-1,0): (-u,n,v), (0,-1): (v,u,-n), (0,1): (-v,u,n)}.items():
            nb = (c[0]+d[0], c[1]+d[1])
            if nb in net and nb not in st: st[nb] = new; stack.append(nb)
    return {net[c]: st[c][0] for c in net}
for k, net in nets.items():
    N = fold(net)
    ok = all(round(np.linalg.det(np.array([N[t], N[r], N[l]]))) == -1 for t, r, l in views)
    print(k, ok)  # A True; B, C, D False
